#include <iostream>
#include <vector>
using namespace std;

class Answer {
public:
    Answer() : day(10), year(365) {}
    int N;
    int day;
    int year;

    unsigned long long count(int cnt);
    void set();
    void OutPut();
    bool empty();
    bool ans();
};

vector<unsigned long long> memo; // Memoization vector

unsigned long long Answer::count(int cnt) {
    if (cnt < 0) return 0;
    if (cnt == 0) return 1;

    // Check if already computed
    if (memo.size() <= cnt) {
        memo.resize(cnt + 1, 0); // Resize if necessary
    }
    if (memo[cnt] != 0) return memo[cnt]; // Return cached value

    unsigned long long a = 1, b = 1, c = 2;
    for (int i = 3; i <= cnt; i++) {
        unsigned long long temp = a + b + c;
        a = b;
        b = c;
        c = temp;
    }
    memo[cnt] = c; // Cache the result
    return c;
}

void Answer::OutPut() {
    if (N == 0) return;
    printf("%d\n", 1 + (count(N)) / (day * year));
}

void Answer::set() {
    cin >> N;
}

bool Answer::empty() {
    return N != 0;
}

bool Answer::ans() {
    set();
    OutPut();
    return empty();
}

int main() {
    Answer ans;
    while (ans.ans());
    return 0;
}

